import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"31、【咸】 艮下兑上","description":"周易口诀义 - 31、【咸】 艮下兑上","frontmatter":{"title":"31、【咸】 艮下兑上","description":"周易口诀义 - 31、【咸】 艮下兑上"},"headers":[],"relativePath":"zh/classics/koujueyi/033.md","filePath":"zh/classics/koujueyi/033.md"}'),r={name:"zh/classics/koujueyi/033.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_31、【咸】-艮下兑上" tabindex="-1">31、【咸】 艮下兑上 <a class="header-anchor" href="#_31、【咸】-艮下兑上" aria-label="Permalink to “31、【咸】 艮下兑上”">​</a></h1><p>彖曰：咸，感也。柔上而刚下，二气感应以相与，止而说，男下女，是以亨利贞，取女吉也。天地感而万物化生，圣人感人心而天下和平，观其所感，而天地万物之情可见矣！</p><p>象曰：山上有泽，咸。君子以虚受人。</p><p>初六：咸其拇。</p><p>象曰：「咸其拇」，志在外也。</p><p>六二：咸其腓，凶，居吉。</p><p>象曰：虽凶居吉，顺不害也。</p><p>九三，咸其股，执其随，往吝。</p><p>象曰：「咸其股」，亦不处也，志在随人，所执下也。</p><p>九四，贞吉，悔亡。憧憧往来，朋从尔思。</p><p>象曰：「贞吉悔亡」，未感害也。「憧憧往来」，未光大也。</p><p>九五，咸其脢，无悔。</p><p>象曰：「咸其脢」，志末也。</p><p>上六，咸其辅颊舌。</p><p>象曰：「咸其辅颊、舌」，滕口说也。</p><p>解读</p><p>「咸，亨，利贞」者，咸，感也，感，应也，以二气交感，所以亨通，感应之道，必须以正，故曰「利贞」也。「取女吉」者，以艮、兑俱是少，相配交感，感而又正，备礼乃行，即是婚取之善也。象曰「山上有泽，咸」者，山体空虚，艮阳泽性润下，兑阴山受泽润，万物以生，是相感之象也。君子以虚受人者，夫欲感人之心，怀来万邦者，必须空虚其心，受纳诸物，无所弃遗。何妥云：「虚心受人，不闲不拒，即物来归己，君子之志也。」</p><p>「初六，咸其拇」者，「拇」是足大指，初六处感之始而应于四，喻体之中，在于足指，相感微浅，故无吉凶悔吝也。</p><p>「六二，咸其腓，凶，居吉」者，「腓」，膊肠也。腓体动躁，或屈或伸，不能安静。若以躁感物，必致凶灾；若静而相感，即怀吉庆。故曰「咸其腓，凶，居吉」。</p><p>「九三，咸其股，执其随，往吝」者，「股」，腿髀也；「随」谓足。九三渐进于腿髀之间。股之为体，动静不能自处，常执随其足。股非动躁之物，而强抑其情。譬之于人，自无特操，卓然独处，而乃随从于人，是所执卑劣。以斯而行，必招恨辱，故曰「往吝」也。</p><p>「九四，贞吉，悔亡。憧憧往来，朋从尔思」者，以阳居阴，邪僻相感，患必生焉，故须贞正获吉，忧悔乃亡，故云「贞吉，悔亡」也。「憧憧」，往来之貌。夫相感之道，固当修德，安处其位，使物自来，即朋党从尔所思，斯未为光大，故小象云「未光大也」。</p><p>「九五，咸其脢，无悔」者，「脢」，背脊也。夫感应之道，贵乎心实。今九五所感在于「脢」，明其非在衷心，薄于交义，故但「无悔」而已。「脢」亦心之上，口之下也。</p><p>上六：咸其辅颊舌。辅颊是言语之具，上六咸道之末，所感在于口舌颊颔之间，不能以心相感，但滕达口舌传说而已，故小象云「滕口说」也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
